-- READ-ONLY: the 35 functions not yet captured. Changes nothing.
select n.nspname, p.proname, pg_get_function_identity_arguments(p.oid) args, pg_get_functiondef(p.oid) def
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where p.prokind='f' and n.nspname='public' and p.proname = any(string_to_array('insurance_visit_billing_context,insurance_workspace,meta_job_retry,meta_publish_issues,meta_requeue_retryable_jobs,my_staff_kpis,patient_portal_journey_action,patient_portal_journey_snapshot,patient_portal_service_reports,performance_available_roles,performance_evidence_review,performance_feedback_queue,performance_feedback_review,performance_set_role_allocations,personal_home_rating_queue,reap_stuck_meta_publish_jobs,refresh_content_learnings,staff_comprehensive_performance,staff_comprehensive_team,staff_kpi_month_data,staff_kpi_scan_alerts,staff_kpis,staff_kpis_admin,staff_summary_fallback,staff_summary_save,task_checklist_add,task_checklist_counts,task_checklist_list,task_checklist_remove,task_checklist_toggle,upcoming_health_occasions,weekly_marketing_report_data,weekly_midweek_nudge,weekly_proposals_to_tasks,weekly_report_fallback',','))
order by 1,2,3;
